/** SymPy's doctests and unit tests of this module with SymPy's printed results. Generated by compat/totests from the SymPy corpora; do not edit. */

import { describe, expect, it } from 'vitest';
import { Add, I, Mul, Pow, Sym, Ynm, YnmC, Znm, add, diff, exp, expand, expandFunc, fn, mul, pi, pow, rational, simplify, symbols } from '../../../src';
import { sympyStr } from '../../sympy-str';

describe("doctests of sympy.functions.special.spherical_harmonics", () => {
  it("Ynm(n, m, theta, phi)", () => {
    const [n, m, theta, phi] = symbols('n m theta phi');
    expect(sympyStr(Ynm(n, m, theta, phi))).toBe('Ynm(n, m, theta, phi)');
  });
  it("Ynm(n, -m, theta, phi)", () => {
    const [n, m, theta, phi] = symbols('n m theta phi');
    expect(sympyStr(Ynm(n, mul(-1, m), theta, phi))).toBe('(-1)**m*exp(-2*I*m*phi)*Ynm(n, m, theta, phi)');
  });
  it("Ynm(n, m, -theta, phi)", () => {
    const [n, m, theta, phi] = symbols('n m theta phi');
    expect(sympyStr(Ynm(n, m, mul(-1, theta), phi))).toBe('Ynm(n, m, theta, phi)');
  });
  it("Ynm(n, m, theta, -phi)", () => {
    const [n, m, theta, phi] = symbols('n m theta phi');
    expect(sympyStr(Ynm(n, m, theta, mul(-1, phi)))).toBe('exp(-2*I*m*phi)*Ynm(n, m, theta, phi)');
  });
  it("simplify(Ynm(0, 0, theta, phi).expand(func=True))", () => {
    expect(sympyStr(simplify(mul(rational(1, 2), pow(pi, rational(-1, 2)))))).toBe('1/(2*sqrt(pi))');
  });
  it("simplify(Ynm(1, -1, theta, phi).expand(func=True))", () => {
    const [phi, theta] = symbols('phi theta');
    expect(sympyStr(simplify(mul(rational(1, 4), pow(6, rational(1, 2)), pow(pi, rational(-1, 2)), exp(mul(-1, I, phi)), fn('sin', [theta]))))).toBe('sqrt(6)*exp(-I*phi)*sin(theta)/(4*sqrt(pi))');
  });
  it("simplify(Ynm(1, 0, theta, phi).expand(func=True))", () => {
    const theta = new Sym('theta');
    expect(sympyStr(simplify(mul(rational(1, 2), pow(3, rational(1, 2)), pow(pi, rational(-1, 2)), fn('cos', [theta]))))).toBe('sqrt(3)*cos(theta)/(2*sqrt(pi))');
  });
  it("simplify(Ynm(1, 1, theta, phi).expand(func=True))", () => {
    const [phi, theta] = symbols('phi theta');
    expect(sympyStr(simplify(mul(rational(-1, 4), pow(6, rational(1, 2)), pow(pi, rational(-1, 2)), exp(mul(I, phi)), fn('sin', [theta]))))).toBe('-sqrt(6)*exp(I*phi)*sin(theta)/(4*sqrt(pi))');
  });
  it("simplify(Ynm(2, -2, theta, phi).expand(func=True))", () => {
    const [phi, theta] = symbols('phi theta');
    expect(sympyStr(simplify(add(mul(rational(1, 8), pow(30, rational(1, 2)), pow(pi, rational(-1, 2)), exp(mul(-2, I, phi))), mul(rational(-1, 8), pow(30, rational(1, 2)), pow(pi, rational(-1, 2)), pow(fn('cos', [theta]), 2), exp(mul(-2, I, phi))))))).toBe('sqrt(30)*exp(-2*I*phi)*sin(theta)**2/(8*sqrt(pi))');
  });
  it("simplify(Ynm(2, -1, theta, phi).expand(func=True))", () => {
    const [theta, phi] = symbols('theta phi');
    expect(sympyStr(simplify(mul(rational(1, 4), pow(30, rational(1, 2)), pow(pi, rational(-1, 2)), fn('cos', [theta]), exp(mul(-1, I, phi)), fn('sin', [theta]))))).toBe('sqrt(30)*exp(-I*phi)*sin(2*theta)/(8*sqrt(pi))');
  });
  it("simplify(Ynm(2, 0, theta, phi).expand(func=True))", () => {
    const theta = new Sym('theta');
    expect(sympyStr(simplify(add(mul(rational(-1, 4), pow(5, rational(1, 2)), pow(pi, rational(-1, 2))), mul(rational(3, 4), pow(5, rational(1, 2)), pow(pi, rational(-1, 2)), pow(fn('cos', [theta]), 2)))))).toBe('sqrt(5)*(3*cos(theta)**2 - 1)/(4*sqrt(pi))');
  });
  it("simplify(Ynm(2, 1, theta, phi).expand(func=True))", () => {
    const [theta, phi] = symbols('theta phi');
    expect(sympyStr(simplify(mul(rational(-1, 4), pow(30, rational(1, 2)), pow(pi, rational(-1, 2)), fn('cos', [theta]), exp(mul(I, phi)), fn('sin', [theta]))))).toBe('-sqrt(30)*exp(I*phi)*sin(2*theta)/(8*sqrt(pi))');
  });
  it("simplify(Ynm(2, 2, theta, phi).expand(func=True))", () => {
    const [phi, theta] = symbols('phi theta');
    expect(sympyStr(simplify(add(mul(rational(1, 8), pow(30, rational(1, 2)), pow(pi, rational(-1, 2)), exp(mul(2, I, phi))), mul(rational(-1, 8), pow(30, rational(1, 2)), pow(pi, rational(-1, 2)), pow(fn('cos', [theta]), 2), exp(mul(2, I, phi))))))).toBe('sqrt(30)*exp(2*I*phi)*sin(theta)**2/(8*sqrt(pi))');
  });
  it("diff(Ynm(n, m, theta, phi), theta)", () => {
    const [n, m, theta, phi] = symbols('n m theta phi');
    expect(sympyStr(diff(fn('Ynm', [n, m, theta, phi]), theta))).toBe('m*cot(theta)*Ynm(n, m, theta, phi) + sqrt((-m + n)*(m + n + 1))*exp(-I*phi)*Ynm(n, m + 1, theta, phi)');
  });
  it("diff(Ynm(n, m, theta, phi), phi)", () => {
    const [n, m, theta, phi] = symbols('n m theta phi');
    expect(sympyStr(diff(fn('Ynm', [n, m, theta, phi]), phi))).toBe('I*m*Ynm(n, m, theta, phi)');
  });
  it("conjugate(Ynm(n, m, theta, phi))", () => {
    const [n, m, theta, phi] = symbols('n m theta phi');
    expect(sympyStr(fn('conjugate', [fn('Ynm', [n, m, theta, phi])]))).toBe('(-1)**(2*m)*exp(-2*I*m*phi)*Ynm(n, m, theta, phi)');
  });
  it("expand_func(Ynm(n, m, theta, phi))", () => {
    const [n, m, theta, phi] = symbols('n m theta phi');
    expect(sympyStr(expandFunc(fn('Ynm', [n, m, theta, phi])))).toBe('sqrt((2*n + 1)*factorial(-m + n)/factorial(m + n))*exp(I*m*phi)*assoc_legendre(n, m, cos(theta))/(2*sqrt(pi))');
  });
  it("Ynm_c(n, m, theta, phi)", () => {
    const [n, m, theta, phi] = symbols('n m theta phi');
    expect(sympyStr(YnmC(n, m, theta, phi))).toBe('(-1)**(2*m)*exp(-2*I*m*phi)*Ynm(n, m, theta, phi)');
  });
  it("Ynm_c(n, m, -theta, phi)", () => {
    const [n, m, theta, phi] = symbols('n m theta phi');
    expect(sympyStr(YnmC(n, m, mul(-1, theta), phi))).toBe('(-1)**(2*m)*exp(-2*I*m*phi)*Ynm(n, m, theta, phi)');
  });
  it("simplify(Ynm_c(0, 0, theta, phi).expand(func=True))", () => {
    expect(sympyStr(simplify(mul(rational(1, 2), pow(pi, rational(-1, 2)))))).toBe('1/(2*sqrt(pi))');
  });
  it("simplify(Ynm_c(1, -1, theta, phi).expand(func=True))", () => {
    const [phi, theta] = symbols('phi theta');
    expect(sympyStr(simplify(mul(rational(1, 4), pow(6, rational(1, 2)), pow(pi, rational(-1, 2)), exp(mul(-1, I, phi)), exp(mul(2, I, fn('conjugate', [phi]))), fn('sin', [theta]))))).toBe('sqrt(6)*exp(I*(-phi + 2*conjugate(phi)))*sin(theta)/(4*sqrt(pi))');
  });
  it("Znm(n, m, theta, phi)", () => {
    const [n, m, theta, phi] = symbols('n m theta phi');
    expect(sympyStr(Znm(n, m, theta, phi))).toBe('Znm(n, m, theta, phi)');
  });
  it("simplify(Znm(0, 0, theta, phi).expand(func=True))", () => {
    expect(sympyStr(simplify(mul(rational(1, 2), pow(pi, rational(-1, 2)))))).toBe('1/(2*sqrt(pi))');
  });
  it("simplify(Znm(1, 1, theta, phi).expand(func=True))", () => {
    const [phi, theta] = symbols('phi theta');
    expect(sympyStr(simplify(add(mul(rational(-1, 4), pow(3, rational(1, 2)), pow(pi, rational(-1, 2)), exp(mul(I, phi)), fn('sin', [theta])), mul(rational(-1, 4), pow(3, rational(1, 2)), pow(pi, rational(-1, 2)), exp(mul(-1, I, phi)), fn('sin', [theta])))))).toBe('-sqrt(3)*sin(theta)*cos(phi)/(2*sqrt(pi))');
  });
  it("simplify(Znm(2, 1, theta, phi).expand(func=True))", () => {
    const [theta, phi] = symbols('theta phi');
    expect(sympyStr(simplify(add(mul(rational(-1, 4), pow(15, rational(1, 2)), pow(pi, rational(-1, 2)), fn('cos', [theta]), exp(mul(I, phi)), fn('sin', [theta])), mul(rational(-1, 4), pow(15, rational(1, 2)), pow(pi, rational(-1, 2)), fn('cos', [theta]), exp(mul(-1, I, phi)), fn('sin', [theta])))))).toBe('-sqrt(15)*sin(2*theta)*cos(phi)/(4*sqrt(pi))');
  });
});

